content.text:
The evidence points to one fault, with its effect running up the chain to the user-facing services.

```json
{
  "root_causes": [
    {
      "service": "ts-basic-service",
      "fault_kind": "network_loss",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, metric, attr_source, attr_destination, count(*) n, round(sum(value),1) total FROM abnormal_metrics_sum WHERE metric='hubble_drop_total' AND value>0 AND attr_source LIKE '%ts-price-service%' AND attr_destination LIKE '%ts-basic-service%' GROUP BY ALL UNION ALL SELECT 'norm' p, metric, attr_source, attr_destination, count(*) n, round(sum(value),1) total FROM normal_metrics_sum WHERE metric='hubble_drop_total' AND value>0 AND attr_source LIKE '%ts-price-service%' AND attr_destination LIKE '%ts-basic-service%' GROUP BY ALL",
          "claim": "Packets dropped on the price-to-basic connection: 17 drops abnormal, none in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, round(c.duration/1e6,1) client_ms, round(s.duration/1e6,1) server_ms, round((epoch(s.time)-epoch(c.time))*1000,1) start_gap_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.attr_span_kind='Client' AND c.service_name='ts-basic-service' AND s.service_name='ts-price-service' ORDER BY client_ms DESC LIMIT 10",
          "claim": "Basic's calls to price take 4-26s on the client while price's server span is only 5-10ms, with ~1s start gaps."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration,0.95)/1e6 client_p95, approx_quantile(s.duration,0.95)/1e6 server_p95 FROM abnormal_traces c JOIN abnormal_traces s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.attr_span_kind='Client' AND c.service_name='ts-basic-service' GROUP BY ALL ORDER BY client_p95 DESC",
          "claim": "Only basic's calls to price show a large client-minus-server gap; calls to route, station and train stay near normal."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-basic-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration,0.95)/1e6 client_p95, approx_quantile(s.duration,0.95)/1e6 server_p95 FROM abnormal_traces c JOIN abnormal_traces s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.attr_span_kind='Client' AND c.service_name='ts-travel-service' AND s.service_name='ts-basic-service' GROUP BY ALL",
          "claim": "Travel's calls to basic inherit the delay: client p95 about 6.5s, matching basic's server time."
        }
      ]
    },
    {
      "from": "ts-basic-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration,0.95)/1e6 client_p95, approx_quantile(s.duration,0.95)/1e6 server_p95 FROM abnormal_traces c JOIN abnormal_traces s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.attr_span_kind='Client' AND c.service_name='ts-travel2-service' AND s.service_name='ts-basic-service' GROUP BY ALL",
          "claim": "Travel2's calls to basic inherit the delay: client p95 about 26s, matching basic's server time."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration,0.95)/1e6 client_p95, approx_quantile(s.duration,0.95)/1e6 server_p95 FROM abnormal_traces c JOIN abnormal_traces s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.attr_span_kind='Client' AND c.service_name='ts-route-plan-service' AND s.service_name='ts-travel-service' GROUP BY ALL",
          "claim": "Route-plan's calls to travel now take about 6.6s at p95, matching travel's server time."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration,0.95)/1e6 client_p95, approx_quantile(s.duration,0.95)/1e6 server_p95 FROM abnormal_traces c JOIN abnormal_traces s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.attr_span_kind='Client' AND c.service_name='ts-route-plan-service' AND s.service_name='ts-travel2-service' GROUP BY ALL",
          "claim": "Route-plan's calls to travel2 now take about 54s at p95, matching travel2's server time."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration,0.95)/1e6 client_p95, approx_quantile(s.duration,0.95)/1e6 server_p95 FROM abnormal_traces c JOIN abnormal_traces s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.attr_span_kind='Client' AND c.service_name='ts-travel-plan-service' AND s.service_name='ts-route-plan-service' GROUP BY ALL",
          "claim": "Travel-plan's calls to route-plan take about 63s at p95, matching route-plan's server time."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, round(duration/1e6,1) ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%travelPlan%' ORDER BY ms DESC LIMIT 5",
          "claim": "User-facing travelPlan requests at ui-dashboard take 20s, while travel-plan's own server spans take up to 63s."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, round(duration/1e6,1) ms FROM abnormal_traces WHERE service_name IN ('ts-ui-dashboard','ts-travel2-service') AND attr_span_kind='Server' AND span_name LIKE '%trips/left%' ORDER BY ms DESC LIMIT 5",
          "claim": "Travel2's trips/left server spans reach 54s while the user-facing dashboard spans show up to 20s for the same flow."
        }
      ]
    }
  ]
}
```

